using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DiceGorgerEffect", menuName = "Data/Battle/Effects/Enemy/DiceGorger Effect")]
public class DiceGorgerEffect : Effect
{
	private const string remainingDiceID = "RemainingDice";

	[NonSerialized]
	private int startingAmount;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedDescription = GetLocalizedDescription();
		if (amount == EffectsValues.NO_VALUE || amount == -1)
		{
			localizedDescription = GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, GetNumberToReplaceWithX(), null);
		}
		else
		{
			localizedDescription = Smart.Format(localizedDescription, startingAmount);
			if (startingAmount > 1)
			{
				localizedDescription = localizedDescription + "\n" + Smart.Format(base.localizationManager.GetLocalizedString("RemainingDice"), amount);
			}
		}
		return localizedDescription;
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		startingAmount = effectAmount;
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (effectAmount > 0)
		{
			if (effectOwner.GetComponent<CorruptedAnimalInitializer>().CorruptedAnimalData.CorruptedAnimalName == "CorruptedChest")
			{
				effectOwner.GetComponent<SpriteControl>().PlayAnimation(AnimationType.Attack, AnimationChangeType.ReturnToIdleAnimation);
				PlayEffectActivationSFX();
			}
			effectOwner.GetComponent<CorruptedAnimalEffects>().IsEffectActiveAndDecreaseEffect(this, 1, activateFeedback: true, removeOnZero: false);
		}
		return effectAmount;
	}

	public override int OptionalActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (!effectOwner.GetComponent<CorruptionStats>().IsDefeated() && startingAmount - effectAmount > 0)
		{
			effectOwner.GetComponent<UnitEffects>().AddEffect(this, startingAmount - effectAmount, effectFeedback: true, callEffectsCallbacks: false);
		}
		return effectAmount;
	}
}
